INSERT INTO `page_feedback_comments` (`id`, `thread_id`, `message_type`, `body`, `attachments`, `created_by_user_id`, `created_by_name`, `created_at`) VALUES ('b0bad6cf-358a-4abf-a8fd-8873b30585c6','0664e852-aefd-4804-93ef-91d88c30c12d','report','Paletsiz yüklemede her ürün için koli CBM\'si = Koli En x Koli Boy x Koli Yükseklik / 1.000.000 formülüyle hesaplanacak; toplam CBM koli adediyle çarpılarak bulunacak. Kabul: Ürün ve teklif toplam CBM değerleri dört ondalık hassasiyetle hesaplanır.\n\nİş paketi: Teklif / Çeki Özeti\nProje: Fuar Teklif\nArayüz referansı: https://claude.ai/public/artifacts/eecb9182-5cad-4d25-a842-494011576965\n\nBu görev Fuar Teklif Modülü altında, mevcut üretim yazılımından ayrı proje olarak takip edilir.','[]',NULL,'Fuar Teklif Görev Dosyası','2026-07-29 22:22:28'),('5778e2bb-9441-11f1-8e61-525400a0bcd9','0664e852-aefd-4804-93ef-91d88c30c12d','comment','Geliştirme başladı. İlk paket: bağımsız fuar_teklif servisi, ürün/müşteri/teklif/revizyon temel şeması ve tek hesaplama motoru eklendi. Takım-koli-palet dönüşümü, MOQ, koli/palet CBM, net-brüt ağırlık, satır tutarı, genel/ek indirim ve EXW/FOB/CIF toplamları testlerle çalışıyor. Bu kartın ekran/kalıcılık/çıktı kabul kriterleri sonraki adımlarda tamamlanacağı için açık tutuluyor.','[]',NULL,'Codex','2026-08-09 22:26:18'),('347d6eb5-944d-11f1-8e61-525400a0bcd9','0664e852-aefd-4804-93ef-91d88c30c12d','comment','İlerleme notu: Paletsiz yüklemede koli en-boy-yükseklik ve koli adedi üzerinden CBM hesabı API ve teklif revizyon detayına bağlandı. Canlı kabul örneği: 10 koli = 0,6 m³. PDF/Excel çıktı karşılaştırması sonrası kapatılacak.','[]',NULL,'Codex','2026-08-09 23:51:13'),('ff64f23e-bd87-4522-8ab2-a7774ef81542','482661d2-76e0-4b82-9bcc-bb2d1652f5ed','report','Birim dönüşümü, MOQ, para birimi, genel/ek indirim, EXW/FOB/CIF toplamı, CBM, palet, net/brüt ağırlık, konteyner/TIR doluluğu ve revizyon geçmişi için test senaryoları hazırlanacak. Temel referans: 3 palet=60 koli=360 takım ve 360 x 9 USD=